// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, bytes16(0), address(this), address(this), address(this)); }
    function testFuzz_property(address caller) public {
        // Ensure caller is not a ward initially
        vm.assume(caller != address(this));
        vm.prank(caller);
        // The rely function should revert if caller is not a ward in the reference
        // In the mutant it would NOT revert because the condition is reversed
        (bool success,) = address(c).call(abi.encodeWithSignature("rely(address)", caller));
        // In the reference, success is false; in the mutant, success is true
        // The assertion: after the call, the caller's ward status should be 1 if and only if the call succeeded
        // But since we only check the invariant that the reference always reverts for non-ward callers:
        // We assert that the call always reverts (success == false)
        assertTrue(!success, "rely should revert for non-ward caller");
    }
}

